public class METDiscountClaimHelper
{
    private SalesQty        invoiceQty;
    private ItemId          itemId;
    private InventDimId     inventDimId;
    private InvoiceId       invoiceId;
    private SalesLine       salesLine;
    private LedgerVoucher   ledgerVoucher;
    private Voucher         voucher;
    private TransDate       transdate;

    private LedgerJournalTable  ledgerJournalTableClaimAccrual;
    private Voucher             voucherClaimAccrual;
    // Reuse GUPParameters for POC but will have to be removed as feature will be disabled
    private GUPParameters       gupParameters;

}

