public void setPostLinesParameters(
    LedgerVoucher   _ledgerVoucher,
    Voucher         _voucher = null,
    TransDate       _transdate = dateNull())
{
    this.ledgerVoucher  = _ledgerVoucher;
    this.voucher        = _voucher;
    this.transdate      = _transdate;
}

public void setDiscountPostParameters(
    SalesQty        _invoiceQty,
    ItemId          _itemId,
    InventDimId     _inventDimId,
    InvoiceId       _invoiceId,
    SalesLine       _salesLine)
{
    this.invoiceQty     = _invoiceQty;
    this.itemId         = _itemId;
    this.inventDimId    = _inventDimId;
    this.invoiceId      = _invoiceId;
    this.salesLine      = _salesLine;
}

    public void distributeDiscountClaim(
        /*RetailSalesDiscountLine _SalesDiscountLine,
        RetailPeriodicDiscount  _Discount,
        RetailDiscountLineOffer _DiscountLineOffer,
        AmountCur               _discountAmountPosted*/)
    {
        METComponentCode componentCode;
        
        // Hardcoded to COGS/440242 for now as we don't have the offset in the POC custom design yet
        //LedgerDimensionDefaultAccount claimOffsetAccount = GUPDiscountVendorClaimPostingProfile::getPostingAccount(_Discount.DiscountClaimPostingOffset);
        const str COGSMainAccount = '440242';
        LedgerDimensionDefaultAccount claimOffsetAccount = LedgerDefaultAccountHelper::getDefaultAccountFromMainAccountId(COGSMainAccount);

        CurrencyCode currencyCode = salesLine.CurrencyCode;
        //int totaldistributionCount = this.getClaimDistributionCount(_SalesDiscountLine);
        int totaldistributionCount = this.getClaimDistributionCount();
        int curdistributionCount = 0;
        AmountCur discAmountDistributed = 0;
        // POC use custom table instead
        //GUPDiscountClaim gupDiscountClaim;
        METDiscountClaim metDiscountClaim;

        // Replace GUPDiscountClaimDistribution by METSalesLinePriceComponentDetail
        //GUPDiscountClaimDistribution claimDistribution;
        METSalesLinePriceComponentDetail salesLinePriceComponentDetail;
        METSalesLinePriceComponent salesLinePriceComponent;

        RecordInsertList ledgerJournalTransRecordList = new RecordInsertList(tableNum(LedgerJournalTrans));

        /*while select claimDistribution
            order by PostingProfileType asc
            where claimDistribution.RefTableId == _SalesDiscountLine.RefTableId
               && claimDistribution.RefRecId   == _SalesDiscountLine.RefRecId
            join DebitAccount from discountClaimPostingProfile
                where discountClaimPostingProfile.Name == claimDistribution.PostingProfile*/
        while select salesLinePriceComponentDetail
                join salesLinePriceComponent
               where salesLinePriceComponentDetail.SalesId == salesLine.SalesId
                  && salesLinePriceComponentDetail.LineNum == salesLine.LineNum
                  && salesLinePriceComponent.SalesId == salesLinePriceComponentDetail.SalesId
                  && salesLinePriceComponent.LineNum == salesLinePriceComponentDetail.LineNum
                  && salesLinePriceComponent.Component == salesLinePriceComponentDetail.Component
            exists join componentCode
                  where componentCode.Component == salesLinePriceComponentDetail.Component
                     && componentCode.Type == GUPPriceComponent::RetailDiscounts
        {
            boolean isClaimDistribution = salesLinePriceComponentDetail.isClaimDistribution();

            // POC just take the value from salesLinePriceComponentDetail (total discount)
            /*if (isClaimDistribution
                || claimDistribution.CalcType == GUPDiscountClaimCalcType::Percent) // Skip calculation type of Amount for additional claim.
            {
                // Free item discount doesn't have _DiscountLineOffer.discAmount, but only percent calc type is allowed for it.
                AmountCur distributeBase = claimDistribution.CalcType == GUPDiscountClaimCalcType::Percent ? 100 : _DiscountLineOffer.discAmount;
                claimDistribution.Value = CurrencyExchangeHelper::amount(claimDistribution.Value * _discountAmountPosted / distributeBase, currencyCode);

                // Handle rounding difference.
                if (isClaimDistribution)
                {
                    curdistributionCount++;
                    discAmountDistributed += claimDistribution.Value;

                    if (curdistributionCount == totaldistributionCount &&  discAmountDistributed != _discountAmountPosted)
                    {
                        claimDistribution.Value += _discountAmountPosted - discAmountDistributed;
                    }
                }
            }
            else
            {
                // Handle calculation type of Amount for additional claim.
                claimDistribution.Value = claimDistribution.Value * invoiceQty;
            }*/



            // Create DiscountClaim and trans.
            /*if (claimDistribution.PostingProfileType == GUPDiscountClaimPostingProfileType::Claim
                || claimDistribution.PostingProfileType == GUPDiscountClaimPostingProfileType::AdditionalClaim)*/
            // only for Claim -> excelude non-claim here
            if (salesLinePriceComponentDetail.Type == METComponentDetailClaimType::Claim)
            {
                // POC create a new claim line everytime as we dont have discount claim transactions underneath
                /*if (!gupDiscountClaim
                    || gupDiscountClaim.DiscountId != _SalesDiscountLine.PeriodicDiscountOfferId
                    || gupDiscountClaim.ClaimType != claimDistribution.PostingProfileType)
                {*/
                    metDiscountClaim = this.createDiscountClaim(salesLinePriceComponent, salesLinePriceComponentDetail);
                //}

                //this.addDiscountClaimTrans(metDiscountClaim.DiscountClaimId, discountClaimPostingProfile.DebitAccount, claimDistribution.Value);
            }

            // POC retrieve the DebitAccount from METComponentCodeDetail
            METComponentCodeDetail componentCodeDetail;
            select firstonly componentCodeDetail 
                       where componentCodeDetail.Component == salesLinePriceComponentDetail.Component
                          && componentCodeDetail.Code      == salesLinePriceComponentDetail.Code;

            // POC default the claim posting profil debit account for accrual to 175010
            const str accrualAccount = '175010';
            LedgerDimensionDefaultAccount debitAccount = LedgerDefaultAccountHelper::getDefaultAccountFromMainAccountId(accrualAccount);

            //this.createClaimAccrualLedgerJournalTrans(claimDistribution.Value, discountClaimPostingProfile.DebitAccount, claimOffsetAccount, ledgerJournalTransRecordList);
            this.createClaimAccrualLedgerJournalTrans(salesLinePriceComponentDetail.Value, debitAccount, claimOffsetAccount, ledgerJournalTransRecordList);
        }

        ledgerJournalTransRecordList.insertDatabase();
    }

    public void postDiscountClaimAccrualJournal()
    {
        if (LedgerJournalTableClaimAccrual)
        {
            LedgerJournalPost::postJournal(LedgerJournalTableClaimAccrual, NoYes::No);

            if (ledgerVoucher)
            {
                this.addLedgerTransVoucherLinkFromLedgerVoucher();
            }
            else
            {
                this.addLedgerTransVoucherLinkFromVoucher(voucher, transDate);
            }
        }
    }

    private void addLedgerTransVoucherLinkFromLedgerVoucher()
    {
        LedgerVoucherObject ledgerVoucherObject = ledgerVoucher.findLedgerVoucherObject();
        Voucher currentVoucher = ledgerVoucherObject.parmSubledgerVoucher();
        TransDate currentTransDate = ledgerVoucherObject.parmTransDate();

        this.addLedgerTransVoucherLinkFromVoucher(currentVoucher, currentTransDate);
    }

    private void addLedgerTransVoucherLinkFromVoucher(Voucher _currentVoucher, TransDate _currentTransDate)
    {
        LedgerTransVoucherLink ledgerTransVoucherLink;

        RecId voucherGroupId = LedgerTransVoucherLink::findVoucherGroupId(_currentVoucher, _currentTransDate);

        if (voucherGroupId == 0)
        {
            ledgerTransVoucherLink.clear();
            ledgerTransVoucherLink.Voucher = _currentVoucher;
            ledgerTransVoucherLink.TransDate = _currentTransDate;
            ledgerTransVoucherLink.insert();

            // The record ID of the first link record is used as the voucher group ID
            voucherGroupId = ledgerTransVoucherLink.RecId;

            // Setting the voucher group ID requires an update after the insert
            ledgerTransVoucherLink.selectForUpdate(true);
            ledgerTransVoucherLink.VoucherGroupId = voucherGroupId;
            ledgerTransVoucherLink.update();
        }

        ledgerTransVoucherLink.clear();
        ledgerTransVoucherLink.VoucherGroupId = voucherGroupId;
        ledgerTransVoucherLink.Voucher = voucherClaimAccrual;
        ledgerTransVoucherLink.TransDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
        ledgerTransVoucherLink.insert();
    }

    //private int getClaimDistributionCount(RetailSalesDiscountLine _SalesDiscountLine)
    private int getClaimDistributionCount()
    {
        /*GUPDiscountClaimDistribution claimDistribution;

        select count(RecId) from claimDistribution
            where claimDistribution.RefTableId == _SalesDiscountLine.RefTableId
               && claimDistribution.RefRecId   == _SalesDiscountLine.RefRecId
               && (claimDistribution.PostingProfileType == GUPDiscountClaimPostingProfileType::Claim
                || claimDistribution.PostingProfileType == GUPDiscountClaimPostingProfileType::NonClaim);

        return int642int(claimDistribution.RecId);*/
        METSalesLinePriceComponentDetail salesLinePriceComponentDetail;

        select count(RecId) from salesLinePriceComponentDetail
            where salesLinePriceComponentDetail.SalesId == salesLine.SalesId
               && salesLinePriceComponentDetail.LineNum == salesLine.LineNum
            && (salesLinePriceComponentDetail.Type == METComponentDetailClaimType::Claim
                || salesLinePriceComponentDetail.Type == METComponentDetailClaimType::NonClaim);

        return int642int(salesLinePriceComponentDetail.RecId);
    }

    /// <summary>
    /// Reuse GUPDiscountClaim for POC
    /// </summary>
    /// <param name = "_discountOfferId"></param>
    /// <param name = "_claimType"></param>
    /// <returns></returns>
    // private GUPDiscountClaim findOrCeateDiscountClaim(RetailPeriodicDiscountOfferId _discountOfferId, GUPDiscountClaimPostingProfileType _claimType)
    private METDiscountClaim createDiscountClaim(METSalesLinePriceComponent _priceComponent, METSalesLinePriceComponentDetail _priceComponentDetails)
    {
        METDiscountClaim metDiscountClaim, metDiscountClaimExist;
        // POC find claimVendorAccount in METClaimSetup
        /*InventItemSalesSetup inventItemSalesSetup = InventItemSalesSetup::find(itemId, inventDimId);
        VendAccount claimVendorAccount = inventItemSalesSetup.GUPDiscountClaimVendorAccount;*/
        METClaimSetup metclaimSetup;
        select firstonly metclaimSetup where metclaimSetup.Component == _priceComponent.Component;
        VendAccount claimVendorAccount = metclaimSetup.Supplier;
        GUPDiscountClaimId claimId;

        LedgerJournalId journalNum = this.getOrCreateClaimAccrualLedgerJournalTable().JournalNum;

        // Claim vendor account is not set.
        if (!claimVendorAccount)
        {
            warning(strFmt("@GlobalUnifiedPricing:VendorAccountForClaimNotSetOnItem", itemId));
            throw error("@SYS21533");
        }

        select firstonly Reference, DiscountClaimId, ClaimType, RecId from metDiscountClaimExist
            where metDiscountClaimExist.SalesInvoice      == invoiceId
               //&& metDiscountClaim.DiscountId        == _discountOfferId
               && metDiscountClaimExist.Reference         == _priceComponent.Reference
               //&& metDiscountClaimExist.Code              == _priceComponentDetails.Code
               && metDiscountClaimExist.VendorAccount     == claimVendorAccount
               && metDiscountClaimExist.AccrualJournalNum == journalNum
               && metDiscountClaimExist.ClaimType         == _priceComponentDetails.Type
               && metDiscountClaimExist.CurrencyCode      == salesLine.CurrencyCode
               && metDiscountClaimExist.Status            == GUPDiscountClaimStatus::Calculated;
        
        // If there is already a claim created for this, add transactions to it without creating new claim.
        /*if (!metDiscountClaim.RecId)
        {
            metDiscountClaim.DiscountClaimId   = NumberSeq::newGetNum(GUPParameters::numRefDiscountClaimId()).num();
            metDiscountClaim.DiscountId        = _discountOfferId;
            metDiscountClaim.VendorAccount     = claimVendorAccount;
            metDiscountClaim.SalesInvoice      = invoiceId;
            metDiscountClaim.AccrualJournalNum = journalNum;
            metDiscountClaim.ClaimType         = _claimType;
            metDiscountClaim.CurrencyCode      = salesLine.CurrencyCode;
            metDiscountClaim.Status            = GUPDiscountClaimStatus::Calculated;
            metDiscountClaim.insert();
        }*/

        if (metDiscountClaimExist)
        {
            claimId = metDiscountClaimExist.DiscountClaimId;
        }
        else
        {
            claimId = NumberSeq::newGetNum(GUPParameters::numRefDiscountClaimId()).num();
        }

        metDiscountClaim.DiscountClaimId   = claimId;
        metDiscountClaim.Reference         = _priceComponent.Reference;
        metDiscountClaim.Code              = _priceComponentDetails.Code;
        metDiscountClaim.SalesId           = _priceComponentDetails.SalesId;
        metDiscountClaim.LineNum           = _priceComponentDetails.LineNum;
        metDiscountClaim.InventTransId     = SalesLine::find(_priceComponentDetails.SalesId, _priceComponentDetails.LineNum).InventTransId;
        metDiscountClaim.VendorAccount     = claimVendorAccount;
        metDiscountClaim.SalesInvoice      = invoiceId;
        metDiscountClaim.AccrualJournalNum = journalNum;
        metDiscountClaim.ClaimType         = _priceComponentDetails.Type;
        metDiscountClaim.CurrencyCode      = salesLine.CurrencyCode;
        metDiscountClaim.Status            = GUPDiscountClaimStatus::Calculated;
        metDiscountClaim.Value             = _priceComponentDetails.Value;
        metDiscountClaim.insert();

        return metDiscountClaim;
    }

    /// <summary>
    /// Reuse GUPParameters for POC
    /// </summary>
    /// <returns></returns>
    private LedgerJournalTable getOrCreateClaimAccrualLedgerJournalTable()
    {
        if (!ledgerJournalTableClaimAccrual)
        {
            if (!gupParameters.DiscountClaimAccrualJournal)
            {
                warning("@GlobalUnifiedPricing:DiscountClaimAccrualJournalError");
                throw error("@SYS21533");
            }

            LedgerJournalName ledgerJournalName = LedgerJournalName::find(gupParameters.DiscountClaimAccrualJournal);
            ledgerJournalTableClaimAccrual = ledgerJournalTableClaimAccrual.pdsInitFromledgerJournalName(ledgerJournalName);
            ledgerJournalTableClaimAccrual.insert();
        }

        return ledgerJournalTableClaimAccrual;
    }

