    private void createClaimAccrualLedgerJournalTrans(AmountCur _amount, LedgerDimensionAccount _account, LedgerDimensionAccount _offsetAccount, RecordInsertList _ledgerJournalTransRecordList)
    {
        LedgerJournalTrans ledgerJournalTrans;
        boolean isPositiveAmount = _amount >= 0;
        date today = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

        ledgerJournalTrans.initValue();
        ledgerJournalTrans.JournalNum = this.getOrCreateClaimAccrualLedgerJournalTable().JournalNum;
        ledgerJournalTrans.Voucher = this.getOrCreateClaimAccrualJournalVoucher();
        ledgerJournalTrans.Txt = "@GlobalUnifiedPricing:DiscountClaimAccrual";
        ledgerJournalTrans.AmountCurDebit = isPositiveAmount ? _amount : 0;
        ledgerJournalTrans.AmountCurCredit = isPositiveAmount ? 0 : -_amount;
        ledgerJournalTrans.Approved = NoYes::Yes;
        ledgerJournalTrans.Approver = HcmWorker::userId2Worker(curUserId());
        ledgerJournalTrans.DocumentDate = today;
        ledgerJournalTrans.TransDate = today;
        ledgerJournalTrans.CurrencyCode = salesLine.CurrencyCode;
        ledgerJournalTrans.LedgerDimension = LedgerDimensionFacade::serviceCreateLedgerDimension(_account);
        ledgerJournalTrans.OffsetLedgerDimension = LedgerDimensionFacade::serviceCreateLedgerDimension(_offsetAccount);
        ledgerJournalTrans.ExchRate = ExchangeRateHelper::exchRate(ledgerJournalTrans.CurrencyCode, ledgerJournalTrans.TransDate);
        ledgerJournalTrans.ExchRateSecond = ExchangeRateHelper::exchRateSecond(ledgerJournalTrans.CurrencyCode, ledgerJournalTrans.TransDate);

        _ledgerJournalTransRecordList.add(ledgerJournalTrans);
    }

    private Voucher getOrCreateClaimAccrualJournalVoucher()
    {
        if (!voucherClaimAccrual)
        {
            LedgerJournalName ledgerJournalName = LedgerJournalName::find(gupParameters.DiscountClaimAccrualJournal);
            NumberSequenceTable numberSequenceTable = NumberSequenceTable::find(ledgerJournalName.NumberSequenceTable);
            NumberSeq numberSeq = NumberSeq::newGetVoucherFromCode(numberSequenceTable.NumberSequence, NumberSeqScopeFactory::createDefaultScope(), false);
            voucherClaimAccrual = numberSeq.voucher();
        }

        return voucherClaimAccrual;
    }
